using SwipeTo.MockSender;
using SwipeTo.Protocol;

const string usage = """
    SwipeTo mock sender — acts like a phone, for testing receivers.

    Usage: SwipeTo.MockSender [options]
      --receiver <id|ws-url>  Receiver id to discover, or ws://host:port/v1 (default: first found)
      --file <path>           Media file to hand off (default: generated bytes, not playable)
      --mime <type>           MIME type (default video/mp4)
      --title <text>          Title (default "Sample video")
      --position <ms>         Hand off at this position (default 42000)
      --duration <ms>         Duration to report (default 600000)
      --code <6dig>           Pairing code to type (default: ask)
      --name <text>           Phone name (default "Mock phone")
      --state-file <path>     Where the sender id and trust tokens are kept
      --aim-hold <ms>         In --script, aim for this long and end the aim before handing off
      --step-delay <ms>       In --script, wait this long before each remote-control step
      --script                Run discover → pair → hello → handoff → pause/seek/play → pull-back and exit

    Interactive keys after handoff:
      space play/pause   ←/→ seek ∓10 s   a aim_start   e aim_end   b bring back   h hand off again   q quit
    """;

var options = new MockSenderOptions();
var script = false;
for (var i = 0; i < args.Length; i++)
{
    string Next() => i + 1 < args.Length ? args[++i] : throw new ArgumentException($"{args[i]} needs a value");
    switch (args[i])
    {
        case "--receiver": options = options with { Receiver = Next() }; break;
        case "--file": options = options with { File = Next() }; break;
        case "--mime": options = options with { Mime = Next() }; break;
        case "--title": options = options with { Title = Next() }; break;
        case "--position": options = options with { PositionMs = long.Parse(Next()) }; break;
        case "--duration": options = options with { DurationMs = long.Parse(Next()) }; break;
        case "--code": options = options with { Code = Next() }; break;
        case "--name": options = options with { Name = Next() }; break;
        case "--state-file": options = options with { StateFile = Next() }; break;
        case "--aim-hold": options = options with { AimHold = TimeSpan.FromMilliseconds(long.Parse(Next())) }; break;
        case "--step-delay": options = options with { StepDelay = TimeSpan.FromMilliseconds(long.Parse(Next())) }; break;
        case "--script": script = true; break;
        default:
            Console.WriteLine(usage);
            return args[i] is "-h" or "--help" ? 0 : 2;
    }
}

await using var app = new MockSenderApp(options);
if (script) return await app.RunScriptAsync() ? 0 : 1;

try
{
    await app.ConnectAsync();
    await app.HandoffAsync();
}
catch (Exception e)
{
    Console.WriteLine($"Could not hand off: {e.Message}");
    return 1;
}

Console.WriteLine("space play/pause · ←/→ seek · a/e aim · b bring back · h hand off again · q quit");
var client = app.Client;
while (true)
{
    var key = Console.ReadKey(intercept: true).Key;
    var position = client.LastState?.PositionMs ?? options.PositionMs;
    try
    {
        switch (key)
        {
            case ConsoleKey.Spacebar:
                await client.ControlAsync(client.LastState?.Playing == true ? ControlAction.Pause : ControlAction.Play);
                break;
            case ConsoleKey.LeftArrow:
                await client.ControlAsync(ControlAction.Seek, Math.Max(0, position - 10_000));
                break;
            case ConsoleKey.RightArrow:
                await client.ControlAsync(ControlAction.Seek, position + 10_000);
                break;
            case ConsoleKey.A:
                await client.AimStartAsync();
                break;
            case ConsoleKey.E:
                await client.AimEndAsync();
                break;
            case ConsoleKey.B:
                var back = await client.PullbackAsync();
                Console.WriteLine($"Back on the phone at {back.PositionMs} ms ({(back.Playing ? "playing" : "paused")})");
                break;
            case ConsoleKey.H:
                await app.HandoffAsync();
                break;
            case ConsoleKey.Q:
                return 0;
        }
    }
    catch (Exception e) when (e is InvalidOperationException or ProtocolException)
    {
        Console.WriteLine($"Not now: {e.Message}");
    }
}
